#!/usr/bin/env bash\nset -e\n\n# Mock rationale: This script runs Terraform locally with no remote backend, ensuring deterministic offline execution.\n\n# Initialize Terraform without remote backend\nterraform init -backend=false > /dev/null\n\n# Validate configuration\nterraform validate\n\n# Generate a plan (no actual apply)\nterraform plan -input=false -out=plan.out > /dev/null\n\n# Ensure the plan contains an aws_s3_bucket resource\nif ! terraform show -json plan.out | grep -q '\"type\":\"aws_s3_bucket\"'; then\n  echo "Test failed: aws_s3_bucket not found in plan"\n  exit 1\nfi\n\necho "All tests passed."
